import{_ as a,o as t,c as o,a2 as d}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Badge","description":"","frontmatter":{},"headers":[],"relativePath":"components/badge.md","filePath":"components/badge.md"}'),i={name:"components/badge.md"};function r(n,e,s,h,c,l){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="badge" tabindex="-1">Badge <a class="header-anchor" href="#badge" aria-label="Permalink to &quot;Badge&quot;">​</a></h1><p>Badge is the label of a state, next to the text it describes.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for a state that changes over time: public, link sharing, can edit, expired. Give one meaning one hue across the application. What a thing is (its kind) is a <a href="./tag">Tag</a>; in one line, Tags come first. A value that can be pressed or removed is a <a href="./chip">Chip</a>. A badge never wraps and is never pressed.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>tone</code></td><td></td><td><code>blue</code>, <code>green</code>, <code>yellow</code>, <code>red</code> or <code>faint</code></td></tr><tr><td><code>children</code></td><td>required</td><td>The word</td></tr></tbody></table><p>Without <code>tone</code> the badge is neutral. Other attributes (<code>aria-*</code>, <code>data-*</code>) go to the element.</p><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The height is <code>--kata-height-badge</code>: the ink of a caption, pad-xs above and below, and a line on each side. pad-sm at the sides; the text is a caption trimmed to its ink. The corners are round, which tells a state from a control. A hue is its fill with the text that reads on it and no visible line; neutral is a strong line and text; faint is a weak line and muted text, for a state that has ended. In a list item the badge keeps md above and below, which makes the item as tall as <code>--kata-height-list-item-mark</code>.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/badge/" title="Badge" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/badge/" target="_blank" rel="noopener">Badge</a></figcaption></figure>',11)])])}const b=a(i,[["render",r]]);export{m as __pageData,b as default};
